import{_ as e,o as r,c as t,ah as i}from"./chunks/framework.C2WMkNym.js";const p=JSON.parse('{"title":"더 알아보기","description":"이미 쓰고 있는 유틸리티 라이브러리와 qsu를 비교하고, 그 라이브러리에서 qsu로 옮기는 방법을 정리했습니다.","frontmatter":{"order":10,"description":"이미 쓰고 있는 유틸리티 라이브러리와 qsu를 비교하고, 그 라이브러리에서 qsu로 옮기는 방법을 정리했습니다."},"headers":[],"relativePath":"ko/discover-more/index.md","filePath":"ko/discover-more/index.md","lastUpdated":1789966801000}'),o={name:"ko/discover-more/index.md"};function s(l,a,d,n,h,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="더-알아보기" tabindex="-1">더 알아보기 <a class="header-anchor" href="#더-알아보기" aria-label="Permalink to &quot;더 알아보기&quot;">​</a></h1><p>대부분의 프로젝트에는 이미 유틸리티 라이브러리가 하나쯤 들어 있습니다. 이 문서 모음은 그 옆에 qsu를 둘 만한지 판단하고, 그렇다면 어떻게 옮길지 결정하는 데 쓰입니다.</p><p><a href="./comparison">비교</a>는 언어별로 가장 널리 쓰이는 유틸리티 라이브러리와 qsu를 나란히 놓고, 각각 어디까지 다루는지, API가 어떤 모양인지, 어디에서 돌아가는지 정리합니다.</p><p>마이그레이션 문서는 라이브러리마다 하나씩 있습니다. 해당 라이브러리의 함수를 qsu 함수에 대응시키고, 이름만 비슷하고 동작이 다른 짝을 표시하며, qsu에 대응 함수가 없는 것도 그대로 적어 둡니다. 어느 것도 그대로 갈아 끼울 수 있는 대체재는 아니니, 무언가를 지우기 전에 비고를 읽으세요.</p><h2 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h2><ul><li><a href="./lodash">Lodash</a></li><li><a href="./underscore">Underscore.js</a></li></ul><h2 id="dart" tabindex="-1">Dart <a class="header-anchor" href="#dart" aria-label="Permalink to &quot;Dart&quot;">​</a></h2><ul><li><a href="./quiver">quiver</a></li><li><a href="./basic-utils">basic_utils</a></li></ul><h2 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to &quot;Python&quot;">​</a></h2><ul><li><a href="./pydash">pydash</a></li><li><a href="./boltons">boltons</a></li></ul>',10)])])}const _=e(o,[["render",s]]);export{p as __pageData,_ as default};
